import { DisjointSets } from '/tmp/ufr/reference/src/dsu.js';

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function groupsOf(labels) {
  const byLabel = new Map();
  labels.forEach((label, element) => {
    if (!byLabel.has(label)) byLabel.set(label, []);
    byLabel.get(label).push(element);
  });
  return [...byLabel.values()].sort((a, b) => a[0] - b[0]);
}

const rnd = mulberry32(0x0f5e7);
const size = 12;
const sets = new DisjointSets(size);
let labels = Array.from({ length: size }, (_, index) => index);
const history = [labels.slice()];
const marks = [];
let unions = 0;

for (let step = 0; step < 4000; step += 1) {
  const roll = rnd();
  if (roll < 0.5) {
    const a = Math.floor(rnd() * size);
    const b = Math.floor(rnd() * size);
    const joined = labels[a] !== labels[b];
    const actualJoined = sets.union(a, b);
    if (actualJoined !== joined) {
      console.log('MISMATCH union at step', step, {a,b,joined,actualJoined});
      process.exit(1);
    }
    if (joined) {
      const from = labels[b];
      const to = labels[a];
      labels = labels.map((label) => (label === from ? to : label));
      unions += 1;
      history[unions] = labels.slice();
    }
  } else if (roll < 0.65) {
    const token = sets.checkpoint();
    if (token !== unions) { console.log('MISMATCH checkpoint at', step, token, unions); process.exit(1); }
    marks.push(token);
  } else if (roll < 0.8 && marks.length > 0) {
    const token = marks[Math.floor(rnd() * marks.length)];
    const undone = sets.rollback(token);
    if (undone !== unions - token) { console.log('MISMATCH rollback at', step, undone, unions-token); process.exit(1); }
    while (marks.length > 0 && marks[marks.length - 1] > token) marks.pop();
    unions = token;
    labels = history[unions].slice();
  } else if (roll < 0.9) {
    const undone = sets.undo();
    if (undone !== (unions > 0)) { console.log('MISMATCH undo at', step, undone, unions>0); process.exit(1); }
    if (undone) {
      unions -= 1;
      labels = history[unions].slice();
      while (marks.length > 0 && marks[marks.length - 1] > unions) marks.pop();
    }
  } else {
    const a = Math.floor(rnd() * size);
    const b = Math.floor(rnd() * size);
    const same = labels[a] === labels[b];
    const conn = sets.connected(a, b);
    if (conn !== same) { console.log('MISMATCH connected at', step, a, b, same, conn); process.exit(1); }
  }
  const expected = groupsOf(labels);
  const actualGroups = sets.groups();
  if (JSON.stringify(expected) !== JSON.stringify(actualGroups)) {
    console.log('MISMATCH groups at step', step, 'expected', expected, 'actual', actualGroups, 'unions', unions);
    process.exit(1);
  }
}
console.log('done, final unions', unions);
EOF
